window.npChooseCreation=function(start){
 const d=document.createElement('dialog');d.setAttribute('aria-label','Create a presentation');d.style.cssText='border:1px solid #d1dfeb;border-radius:16px;padding:28px;width:min(420px,85vw);color:#142e4c;box-shadow:0 20px 70px #142e4c30';
 d.innerHTML='<h2 style="margin:0 0 20px">Create a presentation</h2>';
 for(const [label,kind]of [['Create from a document','document'],['Start from scratch','brief']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.style.cssText='display:block;width:100%;text-align:left;background:white;border:1px solid #c5d8e8;border-radius:9px;padding:18px;margin:10px 0;color:#142e4c;font-weight:600;cursor:pointer';b.onclick=()=>{sessionStorage.setItem('np-workflow-intent',kind);d.close();start();};d.append(b);}
 const b=document.createElement('button');b.textContent='Cancel';b.style.cssText='display:block;margin:18px 0 0 auto;background:white;border:0;color:#54677c;cursor:pointer';b.onclick=()=>d.close();d.append(b);d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal();
};

window.npSessionExpired=function(){
 if(document.getElementById('np-session-expired'))return;
 const d=document.createElement('div');d.id='np-session-expired';d.setAttribute('role','alert');d.style.cssText='position:fixed;bottom:20px;left:50%;transform:translateX(-50%);z-index:99999;background:#fff8e8;color:#142e4c;padding:16px;border:1px solid #dfc78d;border-radius:10px;max-width:90vw';
 const m=document.createElement('span');m.textContent='Your session has expired. Your draft is preserved. ';const b=document.createElement('button');b.textContent='Sign in to continue';b.onclick=()=>location.assign('/api/auth/login?returnTo='+encodeURIComponent(location.pathname+location.search));d.append(m,b);document.body.append(d);
};
